async function processFile(file:File,role:'material'|'template'|'answers'){setError('');let worker:any;const warningPages:number[]=[];try{let content='';let pages=1;const getOcrWorker=async()=>{if(!worker){setProgress(`${t.ocrDownload} (${p.ocrLang})`);const{createWorker}=await import('tesseract.js');worker=await createWorker(p.ocrLang||'deu',1,{logger:(m:any)=>{if(m.status==='recognizing text')setProgress(`${t.ocrWorking} ${Math.round((m.progress||0)*100)}%`)}})}return worker};if(file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf')){const pdfjsLib=await import('pdfjs-dist');const workerAsset=await import('pdfjs-dist/build/pdf.worker.min.mjs?url');pdfjsLib.GlobalWorkerOptions.workerSrc=workerAsset.default;const pdf=await pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;pages=pdf.numPages;for(let i=1;i<=pages;i++){setProgress(`${t.loading} ${i}/${pages}`);const pg=await pdf.getPage(i);const tx=await pg.getTextContent();let pageText=tx.items.map((x:any)=>x.str||'').join(' ').trim();if(pageText.length<35){try{const viewport=pg.getViewport({scale:2});const canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);const ctx=canvas.getContext('2d');if(ctx){await pg.render({canvas,canvasContext:ctx,viewport}).promise;const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,'image/png'));if(blob){const result=await(await getOcrWorker()).recognize(blob);pageText=result.data.text.trim()}}if(pageText.length<20)warningPages.push(i)}catch{warningPages.push(i)}}content+=`\n${pageText}\n`}}else if(file.type.startsWith('image/')){const result=await(await getOcrWorker()).recognize(file);content=result.data.text}else throw new Error(t.unsupportedFormat);const raw=content;content=content.replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim();const d:Doc={id:crypto.randomUUID(),name:file.name,type:file.type,text:content,pages,quality:estimateQuality(content),role,added:new Date().toISOString(),profile:role==='template'?analyzeTemplate(raw):undefined,ocrWarnings:[...new Set(warningPages)]};const updated:Profile={...profileRef.current,docs:[...profileRef.current.docs,d]};profileRef.current=updated;setP(updated);void saveProfile(updated).catch(e=>setError(t.storageWrite+(e instanceof Error?e.message:String(e))));setSelected(x=>role==='material'?[...x,d.id]:x);if(content.length<45)setError(t.noText);const label=pages===1?t.page:t.pages;const line=`${d.name}: ${pages} ${label} · ${textParts(content).length} ${t.sourceCount}${warningPages.length?` · ${t.unreadablePages}: ${warningPages.join(', ')}`:d.quality<.5?` · ${t.needReview}`:''}`;setProgress(line);return line}catch(e){setError(e instanceof Error?e.message:`${t.uploadError} ${t.ocrFirstUse}`);return ''}finally{if(worker)await worker.terminate().catch(()=>{})}}
