function createExam(practice=false,proposed?:Q[]){const chosen=materialDocs.filter(d=>selected.includes(d.id));const docs=practice?materialDocs.filter(d=>!practiceTopic||d.text.toLowerCase().includes(practiceTopic.toLowerCase())):(chosen.length?chosen:materialDocs);if(!docs.length){setError(t.noMaterial);return}const passages=docs.flatMap(d=>textParts(d.text).map(text=>({text,name:d.name,topic:topicOf(text,t.unknownTopic)})));const qs=proposed?.length?proposed:buildGroundedQuestions(passages,practice?3:count,mode==='template'?templateDoc?.profile:undefined,{difficulty:level as Difficulty,language:p.lang,unknownTopic:t.unknownTopic}) as Q[];if(!qs.length){setError(t.noText);return}const title=proposed?.length?`${t.aiReview} · ${new Date().toLocaleDateString()}`:practice?`${t.practiceNow} · ${practiceTopic||t.fallbackTitle}`:`${p.docs.find(d=>selected.includes(d.id))?.name.replace(/\.[^.]+$/,'')||t.new} · ${new Date().toLocaleDateString()}`;const limit=Math.max(5,Math.min(180,Number(mins)||45));const e:Exam={id:crypto.randomUUID(),title,subject:topics[0]||t.fallbackSubject,created:new Date().toISOString(),mode:practice?'practice':mode,questions:qs,duration:practice?0:mode==='exam'?limit:0,timer:!practice&&mode==='exam'?startTimer():undefined};setP(x=>({...x,exams:[e,...x.exams]}));setCurrent(e.id);setActiveQ(0);setNow(Date.now());setPage('take');setError('');setAiQuestions([]);setAiRequest(null);setAiConsent(false)}
