function submitExam(id:string,at=Date.now()){const source=profileRef.current.exams.find(e=>e.id===id&&!e.submitted);if(!source)return;profileRef.current={...profileRef.current,exams:profileRef.current.exams.map(e=>e.id===id?{...e,submitted:true}:e)};const evaluated=source.questions.map(q=>{const result=gradeCreationQuestion(q,q.response,q.points,source.meta?.partialPoints!==false);return{...q,earned:result.points,confidence:result.confidence,uncertain:result.uncertain,missingConcepts:result.missingConcepts,feedback:localFeedback(result,q.response,t),gradedBy:'local' as const}});const weak=[...new Set(evaluated.filter(q=>(q.earned||0)<q.points).map(q=>q.topic))];const elapsed=elapsedSeconds(source.timer,at);setP(x=>({...x,weak:[...new Set([...x.weak,...weak])],minutes:x.minutes+Math.max(1,Math.round(elapsed/60)),exams:x.exams.map(e=>e.id===id?{...e,questions:evaluated,submitted:true,timer:e.timer?{...e.timer,running:false}:undefined}:e)}));setCurrent(id);setPage('result')}
