function correctUploaded(){if(!correctionDoc||!correctionTarget){setError(t.noData);return}if(correctionTarget.submitted&&!confirm(t.correctionConfirm))return;const assigned=extractAnswerAssignments(correctionDoc.text,correctionTarget.questions.length);const uncertain=assigned.size===0;const ocrReview=correctionDoc.quality<.5||(correctionDoc.ocrWarnings?.length||0)>0;const evaluated=correctionTarget.questions.map((q,i)=>{const response=assigned.get(i)||'';const result=gradeCreationQuestion(q,response,q.points,correctionTarget.meta?.partialPoints!==false);return{...q,response,earned:result.points,confidence:result.confidence,uncertain:uncertain||result.uncertain,missingConcepts:result.missingConcepts,feedback:localFeedback(result,response,t,{unassigned:uncertain,ocrReview}),gradedBy:'local' as const}});const weak=[...new Set(evaluated.filter(q=>(q.earned||0)<q.points).map(q=>q.topic))];setP(x=>({...x,weak:[...new Set([...x.weak,...weak])],exams:x.exams.map(e=>e.id===correctionTarget.id?{...e,questions:evaluated,submitted:true,correctionDocId:correctionDoc.id,timer:e.timer?{...e.timer,running:false}:undefined}:e)}));setCurrent(correctionTarget.id);setPage('result');if(ocrReview)setError(`${t.needReview}${(correctionDoc.ocrWarnings?.length||0)?`: ${t.unreadablePages} ${correctionDoc.ocrWarnings!.join(', ')}`:''}`)}
function score(e:Exam){return e.questions.reduce((a,q)=>a+(q.earned||0),0)}function total(e:Exam){return e.questions.reduce((a,q)=>a+q.points,0)}function grade(e:Exam){const pct=total(e)?score(e)/total(e)*100:0;return p.scale.findIndex(n=>pct>=n)+1||6}
function openAiRequest(kind:'questions'|'grade'){if(kind==='questions'&&!createPassages.length){setError(t.noMaterial);return}if(kind==='grade'&&(!exam||!exam.submitted)){setError(t.noExamData);return}let payload:any;if(kind==='questions'){payload={task:'questions',level,profile:mode==='template'?templateDoc?.profile:undefined,sources:createPassages.map((passage,index)=>({index,name:passage.name,topic:passage.topic,text:passage.text}))}}else{const items=(exam?.questions||[]).filter(q=>q.response?.trim()).map(q=>({id:q.id,topic:q.topic,maxPoints:q.points,reference:q.answer,answer:q.response}));if(!items.length){setError(t.noData);return}payload={task:'grade',items}}const preview=JSON.stringify(payload,null,2);setAiPayload(JSON.stringify(payload));setAiPreview(`${t.aiPreview}\n\n${preview}`);setAiRequest(kind);setAiConsent(false);setError('')}
async function performAiRequest(){if(!aiRequest)return;if(!aiConsent){setError(t.aiConsent);return}setAiBusy(true);setError('');const controller=new AbortController();const timeout=window.setTimeout(()=>controller.abort(),30000);try{validateAiConfig(aiConfig);const payload=JSON.parse(aiPayload||'{}');if(aiRequest==='questions'){const sources=createPassages.map(passage=>passage.text);const result=await requestStructured<AiQuestion[]>(aiConfig,`Create ${Math.min(count,12)} exam questions. Style level: ${level}. Use only the supplied source excerpts.`,payload,raw=>validateQuestions(raw,sources,Math.min(count,12)),controller.signal);setAiQuestions(result.map(question=>({id:crypto.randomUUID(),prompt:question.prompt,answer:question.answer,source:createPassages[question.sourceIndex]?.name||t.source,topic:question.topic,points:question.points,response:'',grader:'ai' as const,feedback:t.aiReview})));setError(t.aiApplied)}else{if(!exam||!exam.submitted){setError(t.noExamData);return}const items=(payload.items||[]) as Array<{id:string;maxPoints:number}>;const grades=await requestStructured<Record<string,AiGrade>>(aiConfig,'Grade every answer using only its supplied reference passage. Award partial points and explain missing concepts.',payload,raw=>validateGrades(raw,items.map(item=>({id:item.id,points:item.maxPoints}))),controller.signal);const weakNow=Object.entries(grades).filter(([id,value])=>value.points<(exam.questions.find(q=>q.id===id)?.points||0)).map(([id])=>exam.questions.find(q=>q.id===id)?.topic||'').filter(Boolean);const targetId=exam.id;setP(x=>({...x,weak:[...new Set([...x.weak,...weakNow])],exams:x.exams.map(e=>e.id!==targetId?e:{...e,questions:e.questions.map(q=>{const value=grades[q.id];return value?{...q,earned:value.points,confidence:value.confidence,uncertain:value.confidence<.7,missingConcepts:value.missing,feedback:`${t.aiReview} ${value.explanation}`,gradedBy:'ai' as const}:q})})}));setError(t.aiApplied)}}catch(e){const message=controller.signal.aborted?t.aiTimeout:e instanceof Error?e.message:String(e);setError(`${t.aiUnavailable} ${message}`)}finally{window.clearTimeout(timeout);setAiBusy(false);setAiConsent(false);setAiRequest(null);setAiPreview('');setAiPayload('')}}
function drawRtlText(pdf:any,text:string,x:number,y:number,size:number){const canvas=document.createElement('canvas');const probe=canvas.getContext('2d');if(!probe)return;const fontPx=Math.max(12,Math.round(size*96/25.4));probe.font=`${fontPx}px "Segoe UI","Noto Naskh Arabic",sans-serif`;const width=Math.ceil(probe.measureText(text).width)+12;canvas.width=width;canvas.height=Math.ceil(fontPx*1.7);const draw=canvas.getContext('2d')!;draw.font=probe.font;draw.direction='rtl';draw.textAlign='right';draw.fillStyle='#111827';draw.fillText(text,canvas.width-4,Math.round(fontPx*1.25));const widthMm=width/(96/25.4);pdf.addImage(canvas.toDataURL('image/png'),'PNG',x,y-size*.45,widthMm,canvas.height/(96/25.4));return widthMm}
function drawPdfLine(pdf:any,item:any){const y=item.y||22;if(item.image){try{pdf.addImage(item.image.src,item.image.format||'PNG',item.x,y-item.image.height,item.image.width,item.image.height)}catch{}return}if(item.cells){let x=item.x;const inner=item.size*.48+1.4;for(const cell of item.cells){if(item.header){pdf.setFillColor(241,239,254);pdf.rect(x,y-item.height,cell.width,item.height,'F')}pdf.setDrawColor(item.header?205:222);pdf.rect(x,y-item.height,cell.width,item.height,'S');cell.lines.forEach((text:string,index:number)=>{const lineY=y-item.height+inner+index*inner+item.size*.35;if(isRtlText(text)){const width=Math.ceil(probeWidth(text,item.size));drawRtlText(pdf,text,x+Math.max(2,cell.width-width-2),lineY,item.size)}else{pdf.setFont('helvetica');pdf.setFontSize(item.size);pdf.text(text,x+2,lineY,{maxWidth:cell.width-4})}});x+=cell.width}return}if(!item.text){pdf.setDrawColor(220);pdf.line(22,y+1.5,190,y+1.5);return}if(isRtlText(item.text)){drawRtlText(pdf,item.text,item.x,y,item.size)}else{pdf.setFont('helvetica');pdf.setFontSize(item.size);pdf.text(item.text,item.x,y)}}
function probeWidth(text:string,size:number){const canvas=document.createElement('canvas');const ctx=canvas.getContext('2d');if(!ctx)return size*text.length*.6;const fontPx=Math.max(12,Math.round(size*96/25.4));ctx.font=`${fontPx}px "Segoe UI","Noto Naskh Arabic",sans-serif`;return ctx.measureText(text).width/(96/25.4)}
function drawPdfPages(pdf:any,pages:any[][]){pages.forEach((items,index)=>{if(index)pdf.addPage();for(const item of items)drawPdfLine(pdf,item)})}
async function finishPdf(pdf:any,filename:string){const count=pdf.getNumberOfPages();pdf.setFontSize(9);for(let i=1;i<=count;i++){pdf.setPage(i);pdf.text(`${t.pageWord} ${i} / ${count}`,190,287,{align:'right'})}const bytes=pdf.output('arraybuffer');const result=await saveBlobFile(new Blob([bytes],{type:'application/pdf'}),filename,{dialogTitle:t.shareFile});setProgress(`${t.fileSaved}: ${result.name}`);if(result.error)setError(`${t.shareFailed}: ${result.error}`)}
async function exportPDF(e:Exam,answers=false){setProgress(t.exporting);const{jsPDF}=await import('jspdf');const pdf=new jsPDF({format:'a4',unit:'mm'});const questions=e.questions.map(q=>({prompt:q.prompt,answer:q.answer,points:q.points,response:q.response,earned:q.earned,topic:q.topic,source:q.source,format:q.formatId?formatLabel(q.formatId,t):undefined,options:q.options,correctIndex:q.correctIndex,operator:q.operator?operatorLabel(q.operator,t):undefined,requirementLevel:q.requirementLevel}));const blocks=buildExamPdfBlocks({title:e.title,created:e.created,subject:e.subject,gradeLevel:e.meta?.gradeLevel,goal:e.meta?.goal,objectives:e.meta?.objectives,headerName:e.meta?.headerName,headerClass:e.meta?.headerClass,headerDate:e.meta?.headerDate,gradingScale:p.scale.join(' / '),questions},answers,{date:t.date,points:t.points,solution:t.solution,answer:t.answer,achieved:t.achieved,pointsShort:t.pointsWord,format:t.wizBlockFormat,objectives:t.wizResultObjectives,name:t.wizHeaderName,classLabel:t.wizHeaderClass,subject:t.subjectLabel,grade:t.wizGrade,correct:t.wizQuestionCorrect,operator:t.wizBlockOperator,requirement:t.wizBlockRequirement,gradingScale:t.gradeScale});drawPdfPages(pdf,paginateBlocks(blocks));await finishPdf(pdf,workPdfFilename(e,{suffix:answers?'Musterloesung':''}))}
async function reportPDF(){setProgress(t.exporting);const{jsPDF}=await import('jspdf');const pdf=new jsPDF({format:'a4',unit:'mm'});const blocks=buildReportPdfBlocks({title:t.reportTitle,submitted:learning.submitted,minutes:learning.minutes,percent:learning.percent,weakest:learning.weakest,topics:learning.topics,trend:learning.trend},{exams:t.reportExams,minutes:t.reportMinutes,average:t.avgScore,weak:t.reportWeak,none:t.noWeak,topics:t.topicResults,trend:t.reportTrend});drawPdfPages(pdf,paginateBlocks(blocks));await finishPdf(pdf,progressPdfFilename())}

function deleteAll(){if(confirm(t.deleteConfirm)){deletingRef.current=true;profileRef.current=empty;setP(empty);void clearProfile().catch(e=>setError(t.storageWrite+(e instanceof Error?e.message:String(e))));setSelected([]);setCorrectionDocId('');setCorrectionTargetId('');setStudioArtifact(null);setStudioTool('assistant');historyRef.current=['dashboard'];setPage('dashboard');setError('');setProgress('')}}function removeDoc(id:string){if(!confirm(t.deleteFileConfirm))return;setP(x=>({...x,docs:x.docs.filter(d=>d.id!==id)}));setSelected(x=>x.filter(z=>z!==id))}function navItem(key:string,Icon:any,label?:string){return <button className={`navitem ${page===key?'active':''}`} onClick={()=>go(key)}><Icon size={19}/><span>{label||t[key]}</span></button>}
const allWorks=useMemo(()=>p.exams.slice().sort((a,b)=>b.created.localeCompare(a.created)),[p.exams]);
const worksSubjects=useMemo(()=>[...new Set(p.exams.map(e=>e.subject).filter(Boolean))].sort((a,b)=>a.localeCompare(b)),[p.exams]);
const filteredWorks=useMemo(()=>allWorks.filter(e=>{const q=worksQuery.trim().toLowerCase();const matchQ=!q||e.title.toLowerCase().includes(q)||e.subject.toLowerCase().includes(q)||e.questions.some(x=>x.prompt.toLowerCase().includes(q));const matchS=!worksSubject||e.subject===worksSubject;return matchQ&&matchS}),[allWorks,worksQuery,worksSubject]);
function renameWork(e:Exam){const title=prompt(t.renameWorkPrompt,e.title)?.trim();if(!title)return;setP(x=>({...x,exams:x.exams.map(item=>item.id===e.id?{...item,title}:item)}));setProgress(t.workSaved)}
function deleteWork(e:Exam){if(!confirm(t.deleteWorkConfirm))return;setP(x=>({...x,exams:x.exams.filter(item=>item.id!==e.id)}));if(current===e.id){setCurrent(null);setPage('works')}setProgress(t.workDeleted)}
function assignDoc(e:Exam,field:'solutionDocId'|'correctionDocId',roles:Doc['role'][]){const eligible=p.docs.filter(d=>roles.includes(d.role));if(!eligible.length){setError(t.noDocs);return}const options=eligible.map((d,i)=>`${i+1}. ${d.name}`).join('\n');const choice=prompt(`${t[field==='solutionDocId'?'assignSolution':'assignCorrection']}\n${options}`,'1');const doc=eligible[Number(choice)-1];if(!doc)return;setP(x=>({...x,exams:x.exams.map(item=>item.id===e.id?{...item,[field]:doc.id}:item)}));setProgress(t.workSaved)}
